import{_ as n,o as s,c as i,a2 as a}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Inscription","description":"","frontmatter":{},"headers":[],"relativePath":"guide/professions/inscription.md","filePath":"guide/professions/inscription.md"}'),r={name:"guide/professions/inscription.md"};function o(t,e,l,c,p,d){return s(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="inscription" tabindex="-1">Inscription <a class="header-anchor" href="#inscription" aria-label="Permalink to &quot;Inscription&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> <strong>Implementation:</strong> this redesign is not established as implemented. <strong>Availability:</strong> not established as live. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-09 against Batch 04.</p><p><a href="/Syrolands-Public/game-design/professions/inscription.html">Full design specification</a></p><p>Inscription is proposed as magical engineering: recording, preserving and carefully changing written magical structures. Scrolls are one product; glyphs, variant notation, indexed grimoires, wards and ritual diagrams are other candidate specializations.</p><p>Skill supports execution, learned techniques/schools supply methods and profession paths express specialization. A scribe might become known for combat scrolls, rare variants or well-organized books. Technique names and ward/ritual scope are not final.</p><p>Magery, known patterns, reagents and Alchemy can interact with the craft. Buying an ordinary casting scroll would not buy permanent knowledge; copying and player teaching need explicit rules. Secrets, production, commissions and reputation follow the <a href="/Syrolands-Public/guide/professions/overview.html">shared profession proposal</a>.</p><p>Prepared scrolls may offer faster emergency reference at consumable cost. Rare physical grimoires and reagents remain exposed to loot risk; workmanship does not grant insurance. <a href="/Syrolands-Public/guide/magic/spellbooks-scrolls-and-reagents.html">Books and materials</a> · <a href="/Syrolands-Public/guide/magic/variants-and-glyphs.html">Variants</a>.</p>',7)])])}const u=n(r,[["render",o]]);export{m as __pageData,u as default};
